        private async static Task<(int lastIndex, List<Genre> genres)> AddGenres(DbContext context)
        {
            var i = 0;
            var genres = new List<Genre>
            {
                new() { GenreId = ++i, Name = "Pop" },
                new() { GenreId = ++i, Name = "Rock" },
