                new() { GenreId = ++i, Name = "R&B" },
                new() { GenreId = ++i, Name = "Indie" },
                new() { GenreId = ++i, Name = "Punk" },
                new() { GenreId = ++i, Name = "World" }
            };

            genres.ForEach(s => context.Set<Genre>().Add(s));
            await context.SaveChangesAsync();
            return (i, genres);
